export function parseCSV(text) {
  if (!text || text === '') return [];

  // First pass: split into records, respecting quoted fields
  const records = [];
  let currentRecord = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];

    if (inQuotes) {
      if (char === '"') {
        // Check for escaped quote ""
        if (i + 1 < text.length && text[i + 1] === '"') {
          currentRecord += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        currentRecord += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === '\n' || char === '\r') {
        records.push(currentRecord);
        currentRecord = '';
        // Skip \r\n
        if (char === '\r' && i + 1 < text.length && text[i + 1] === '\n') {
          i++;
        }
      } else {
        currentRecord += char;
      }
    }
  }

  records.push(currentRecord);

  // Remove trailing empty record caused by a trailing newline
  if (records.length > 0 && records[records.length - 1] === '') {
    records.pop();
  }

  // Second pass: parse fields within each record
  return records.map(record => {
    const fields = [];
    let currentField = '';
    let inQuotes = false;

    for (let i = 0; i < record.length; i++) {
      const char = record[i];

      if (inQuotes) {
        if (char === '"') {
          if (i + 1 < record.length && record[i + 1] === '"') {
            currentField += '"';
            i++;
          } else {
            inQuotes = false;
          }
        } else {
          currentField += char;
        }
      } else {
        if (char === '"') {
          inQuotes = true;
        } else if (char === ',') {
          fields.push(currentField);
          currentField = '';
        } else {
          currentField += char;
        }
      }
    }

    if (inQuotes) {
      throw new SyntaxError('Unclosed quoted field');
    }

    fields.push(currentField);
    return fields;
  });
}

